#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<int> v(N);
    for (int i = 0; i < N; i++) {
        cin >> v[i];
    }

    vector<int> vals = v;
    sort(vals.begin(), vals.end());
    vals.erase(unique(vals.begin(), vals.end()), vals.end());

    int ans = 1;

    for (int i = 0; i < (int)vals.size(); i++) {
        for (int j = i + 1; j < (int)vals.size(); j++) {
            int a = vals[i];
            int b = vals[j];

            int cnt = 0;
            int last = -1;

            for (int x : v) {
                if (x == a || x == b) {
                    if (cnt == 0 || x != last) {
                        cnt++;
                        last = x;
                    }
                }
            }

            ans = max(ans, cnt);
        }
    }

    cout << ans << '\n';

    return 0;
}
